SELECT T0."CheckNum", T0."DueDate", T0."CheckSum", T0."Currency", T0."CheckAct" as "Check G/L Account", T0."ManualChk", T0."BankCode" as "Bank Code", T0."AcctNum", T1."CardCode", T1."CardName",  T1."DocNum" as "Outgoing Payment No.", T1."DocDate" as "Outgoing Payment Posting Date", DAYS_BETWEEN(CURRENT_DATE, T0."DueDate" ) as "No. of Days to Check Date" , T0."U_Posted", T0."U_Issued", T0."U_Approved", T0."U_RECNM" FROM VPM1 T0  INNER JOIN OVPM T1 ON T0."DocNum" = T1."DocEntry" WHERE DAYS_BETWEEN(CURRENT_DATE,T0."DueDate") <= 7 and T0."U_Posted"<>'Y'
